def minSessions(tasks, sessionTime):
    tasks.sort(reverse=True)
    n = len(tasks)

    # Memoization dictionary
    memo = {}

    def backtrack(index, sessions):
        if index == n:
            return len(sessions)

        key = (index, tuple(sessions))
        if key in memo:
            return memo[key]

        min_sessions = float('inf')

        # Try to add the current task to an existing session
        for i in range(len(sessions)):
            if sessions[i] + tasks[index] <= sessionTime:
                sessions[i] += tasks[index]
                min_sessions = min(min_sessions, backtrack(index + 1, sessions))
                sessions[i] -= tasks[index]

        # Create a new session for the current task
        sessions.append(tasks[index])
        min_sessions = min(min_sessions, backtrack(index + 1, sessions))
        sessions.pop()

        memo[key] = min_sessions
        return min_sessions

    return backtrack(0, [])

